from typing import List, Dict, Any

# Placeholder for request/response models. 
# Will be populated as specific integration needs arise.

class ImageLabel:
    def __init__(self, name: str, confidence: float):
        self.name = name
        self.confidence = confidence

    def to_dict(self):
        return {"Name": self.name, "Confidence": self.confidence}

class ImageLabelResponse:
    def __init__(self, labels: List[ImageLabel]):
        self.labels = labels

    def to_dict(self):
        return {"Labels": [label.to_dict() for label in self.labels]}

from typing import List, Dict, Any
