class DetectedText:
    def __init__(self, text: str, confidence: float, bounding_box: Dict[str, float]):
        self.text = text
        self.confidence = confidence
        self.bounding_box = bounding_box

    def to_dict(self):
        return {"Text": self.text, "Confidence": self.confidence, "BoundingBox": self.bounding_box}

class DetectTextResponse:
    def __init__(self, text_detections: List[DetectedText]):
        self.text_detections = text_detections

    def to_dict(self):
        return {"TextDetections": [text.to_dict() for text in self.text_detections]}

